def closest_elements(numbers: List[float], threshold: float) -> List[float]:
    """ Return a list of elements which are closer to each other than given threshold.
    >>> closest_elements([1.0, 2.0, 3.0], 0.5)
    []
    >>> closest_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    [2.8, 2.0]
    """
    close_pairs = []
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                close_pairs.extend([numbers[i], numbers[j]])
    return close_pairs


