def longest_common_prefix(strs: List[str]) -> str:
    """Return the longest common prefix string amongst an array of strings.
    If there is no common prefix, return an empty string "".
    """
    if not strs:
        return ''
    if len(strs) == 1:
        return strs[0]

    first, rest = strs[0], strs[1:]
    for prefix in all_prefixes(first):
        if all(map(lambda s: s.startswith(prefix), rest)):
            return prefix
    return ''


def longest_common_suffix(strs: List[str]) -> str:
    """Return the longest common suffix string amongst an array of strings.
    If there is no common suffix, return an empty string "".
    """
    if not strs:
        return ''
    if len(strs) == 1:
        return strs[0]

    first, rest = strs[0], strs[1:]
    for suffix in all_suffixes(first):
        if all(map(lambda s: s.endswith(suffix), rest)):
            return suffix
    return ''


