def gcd(a: int, b: int) -> int:
    """Compute GCD of a and b"""
    return a if b == 0 else gcd(b, a%b)


def lcm(a: int, b: int) -> int:
    """Compute LCM of a and b"""
    return a*b // gcd(a, b)


def egcd(a: int, b: int):
    """ Return tuple (g, x, y), such that ax + by = g = gcd(a, b)"""
    if b == 0:
        return (a, 1, 0)
    else:
        g, x1, y1 = egcd(b, a%b)
        x = y1
        y = x1 - y1*(a//b)
        return (g, x, y)


def modInverse(a: int, m: int) -> int:
    """ Return modular inverse of a mod m """
    g, x, _ = egcd(a, m)
    if g != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x%m


def powmod(x: int, y: int, m: int) -> int:
    """Return (x^y) mod m"""
    if y == 0:
        return 1
    elif y == 1:
        return x
    p = powmod(x, y//2, m)
    return p*p*m if y%2 else p*p%m


def pollard_rho(n: int) -> int:
    """Return non-trivial factor of n using pollard rho algorithm"""
    def f(x):
        return (x*x + 1)%n
    x = y = 2
    d = 1
    while d == 1:
        x = f(x)
        y = f(f(y))
        d = gcd(abs(x - y), n)
    return d


