def synthetic_div(xs: list, x: float):
    """ returns coefficients after synthetic division """
    xs = xs[::-1]
    r = []
    for i, coeff in enumerate(xs):
        if i == 0:
            r.append(coeff)
        else:
            r.append(coeff + x * r[-1])
    return r[::-1][1:]  # skip the last item which is remainder


