def flatten_dict(d: dict):
    """Flatten a dictionary of dictionaries into a single dictionary
    >>> flatten_dict({'a': {'x': 1, 'y': 2}, 'b': {'z': 3}})
    {'a_x': 1, 'a_y': 2, 'b_z': 3}
    """
    return {f"{key}_{subkey}": value for key, subdict in d.items() for subkey, value in subdict.items()}

def transpose_list_of_dicts(list_of_dicts: list):
    """Transpose a list of dictionaries into a dictionary of lists
    >>> transpose_list_of_dicts([{'a': 1, 'b': 2}, {'a': 3, 'b': 4}])
    {'a': [1, 3], 'b': [2, 4]}
    """
    return {key: [d[key] for d in list_of_dicts] for key in list_of_dicts[0]}

def transpose_dict_of_lists(dict_of_lists: dict):
    """Transpose a dictionary of lists into a list of dictionaries
    >>> transpose_dict_of_lists({'a': [1, 3], 'b': [2, 4]})
    [{'a': 1, 'b': 2}, {'a': 3, 'b': 4}]
    """
    return [dict(zip(dict_of_lists, values)) for values in zip(*dict_of_lists.values())]

