def group_by_frequency(l: list):
    """Return a list of lists, where each sublist contains the elements of the original list that are equal to each other,
    sorted by the frequency of the elements in the input list, from highest to lowest frequency.
    >>> group_by_frequency([1, 2, 2, 3, 4, 4, 4])
    [[4, 4, 4], [2, 2], [1], [3]]
    """
    freq = frequency(l)
    grouped = {}
    for i in l:
        if i in grouped:
            grouped[i].append(i)
        else:
            grouped[i] = [i]
    sorted_grouped = sorted(grouped.items(), key=lambda x: freq[x[0]], reverse=True)
    return [v for k, v in sorted_grouped]

