def min_enclosing_circle(A: list):
    """Return the minimal enclosing circle of a set of points.

    >>> A = [(0, 0), (0, 1), (1, 0), (1, 1)]
    >>> min_enclosing_circle(A)
    (0.5, 0.5, 0.7071067811865476)
    >>> A = [(0, 0), (0, 1), (1, 0)]
    >>> min_enclosing_circle(A)
    (0.5, 0.5, 0.5)
    >>> A = [(1, 1), (2, 2), (2, 0)]
    >>> min_enclosing_circle(A)
    (1.6666666666666667, 1.0, 1.1547005383792515)
    """
    from scipy.spatial import ConvexHull
    from math import sqrt

    def dist(p1, p2):
        return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def circle_from(A, B, C):
        # Circumcircle of triangle ABC
        d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]))
        ux = ((A[0] ** 2 + A[1] ** 2) * (B[1] - C[1]) + (B[0] ** 2 + B[1] ** 2) * (C[1] - A[1]) + (C[0] ** 2 + C[1] ** 2) * (A[1] - B[1])) / d
        uy = ((A[0] ** 2 + A[1] ** 2) * (C[0] - B[0]) + (B[0] ** 2 + B[1] ** 2) * (A[0] - C[0]) + (C[0] ** 2 + C[1] ** 2) * (B[0] - A[0])) / d
        r = dist(A, (ux, uy))
        return (ux, uy, r)

    def min_circle_triangulation(A):
        if len(A) == 0:
            return (0, 0, 0)
        if len(A) <= 3:
            if len(A) == 1:
                return (A[0][0], A[0][1], 0)
            elif len(A) == 2:
                ux, uy = ((A[0][0] + A[1][0]) / 2, (A[0][1] + A[1][1]) / 2)
                r = dist(A[0], A[1]) / 2
                return (ux, uy, r)
            else:
                return circle_from(A[0], A[1], A[2])
        hull = ConvexHull(A)
        vertices = [A[i] for i in hull.vertices]
        c = min_circle_triangulation(vertices[1:])
        if dist(vertices[0], c[:2]) <= c[2]:
            return c
        return min_circle_triangulation(vertices[:-1])

    return min_circle_triangulation(A)


