-- Function to find the largest prime factor
CREATE FUNCTION largest_prime_factor(n INT)
RETURNS INT
DETERMINISTIC
BEGIN
    DECLARE largest_prime INT DEFAULT NULL;
    DECLARE factor INT DEFAULT 2;

    WHILE n > 1 DO
        IF n % factor = 0 THEN
            SET largest_prime = factor;
            WHILE n % factor = 0 DO
                SET n = FLOOR(n / factor);
            END WHILE;
        END IF;
        SET factor = factor + 1;
    END WHILE;

    RETURN largest_prime;
END;

