    for char in encoded_message:
        if char.isalpha():
            if char in shifted_vowels:
                if char.islower():
                    decoded_message += chr((ord(char) - ord('a') - 2) % 26 + ord('a')).upper()
                else:
                    decoded_message += chr((ord(char) - ord('A') - 2) % 26 + ord('A')).lower()
            else:
                decoded_message += char.swapcase()
        else:
            decoded_message += char
    return decoded_message

