def _max_heap(arr, k):
    """
    This helper function uses a max heap to find the k largest elements in the array.
    """
    import heapq
    # Create a max heap by negating the elements
    heap = [-x for x in arr]
    heapq.heapify(heap)
    # Extract the k largest elements from the heap
    return sorted([-heapq.heappop(heap) for _ in range(k)])

def _selection_sort(arr, k):
    """
    This helper function uses a selection sort algorithm to find the k largest elements in the array.
    """
    # Sort the array
    sorted_arr = sorted(arr)
    # Return the last k elements
    return sorted_arr[-k:]
